                raise ValueError(f"chunk_size must be positive, got {chunk_size}")
            chunks = [text[i : i + chunk_size] for i in range(0, len(text), chunk_size)]
        else:
            chunks = [text]

        def _encode_chunk(chunk: str) -> list[int]:
            try:
                return self._core_bpe.encode(chunk, allowed_special)
            except UnicodeEncodeError:
                chunk = chunk.encode("utf-16", "surrogatepass").decode("utf-16", "replace")
                return self._core_bpe.encode(chunk, allowed_special)

        encoded_chunks = [_encode_chunk(chunk) for chunk in chunks]

        if not return_repeated_pattern:
            if chunk_size is None:
                return encoded_chunks[0]
            return encoded_chunks

        def _repeated_pattern(tokens: list[int]) -> dict[tuple[int, int], int]:
            counter: Counter[tuple[int, int]] = Counter()
            for a, b in zip(tokens[:-1], tokens[1:]):
                counter[(a, b)] += 1
            return dict(counter.most_common(3))

        if chunk_size is None:
            return encoded_chunks[0], _repeated_pattern(encoded_chunks[0])
        return [
            (tokens, _repeated_pattern(tokens)) for tokens in encoded_chunks
        ]
